import { writeFileSync, mkdirSync, existsSync } from "fs";
import { dirname } from "path";
import { getConfigPath, loadConfig, resolveProjectsDirs } from "../lib/config";
import { capableBunBinaries, capabilityAdvice } from "../lib/caps";
import { getForegroundPid } from "../lib/pidfile";
import { getServiceStatus, isSystemdAvailable } from "../lib/systemd";
import type { Config } from "../lib/types";

const DEFAULT_CONFIG = `# LazyDev Configuration
# Generated by 'lazydev init'

settings:
  proxy_port: 80
  # projects_dir: ~/projects  # or a list: [~/projects, ~/work]

# aliases:
#   mp: myproject             # http://mp.localhost → ~/projects/myproject
#   web: monorepo/apps/web    # nested paths work too
#   grafana: 3000             # a port: Docker containers, servers elsewhere
`;

const DNSMASQ_CONFIG = "address=/localhost/127.0.0.1";

function resolvesToLoopback(name: string): boolean {
  const result = Bun.spawnSync(["getent", "hosts", name], { stdout: "pipe", stderr: "ignore" });
  if (result.exitCode !== 0) return false;
  const address = result.stdout.toString().trim().split(/\s+/)[0] ?? "";
  return address === "::1" || address.startsWith("127.");
}

function checkPort(port: number): "ok" | "in-use" | "denied" | string {
  try {
    const probe = Bun.serve({ port, hostname: "127.0.0.1", fetch: () => new Response() });
    probe.stop(true);
    return "ok";
  } catch (err) {
    const code = (err as { code?: string } | null)?.code;
    if (code === "EADDRINUSE") return "in-use";
    if (code === "EACCES") return "denied";
    return err instanceof Error ? err.message : String(err);
  }
}

function proxyIsRunning(): boolean {
  return (isSystemdAvailable() && getServiceStatus().active) || getForegroundPid() !== null;
}

export async function run() {
  console.log("Initializing LazyDev...\n");

  const configPath = getConfigPath();
  if (!existsSync(configPath)) {
    mkdirSync(dirname(configPath), { recursive: true });
    writeFileSync(configPath, DEFAULT_CONFIG);
    console.log(`✓ Created config file: ${configPath}`);
  } else {
    console.log(`✓ Config file exists: ${configPath}`);
  }

  const config = loadConfig(configPath);
  const port = config.settings.proxy_port;
  const projectsDir = resolveProjectsDirs(config)[0] ?? "~/projects";
  const actionNeeded = checkSetup(config);

  console.log(actionNeeded ? "\nFix the items above, then:" : "\nNext steps:");
  console.log("  1. Start the proxy:     lazydev start");
  console.log(`  2. Start a dev server:  cd ${projectsDir}/myproject && bun dev`);
  console.log(`  3. Open:                http://myproject.localhost${port === 80 ? "" : `:${port}`}  (or: lazydev open)`);
  console.log("  Optional alias:         lazydev alias mp myproject");
}

/** Print setup checks; returns true when something needs fixing. */
export function checkSetup(config: Config): boolean {
  const port = config.settings.proxy_port;
  const projectsDirs = resolveProjectsDirs(config);
  let actionNeeded = false;

  for (const dir of projectsDirs) {
    if (existsSync(dir)) {
      console.log(`✓ Projects directory: ${dir}`);
    } else {
      console.log(`⚠ Projects directory does not exist: ${dir}`);
      console.log("  Create it, or set settings.projects_dir in the config.");
      actionNeeded = true;
    }
  }

  if (resolvesToLoopback("lazydev-check.localhost")) {
    console.log("✓ *.localhost resolves to loopback");
  } else {
    console.log("⚠ *.localhost does not resolve on this system");
    console.log("  Browsers resolve *.localhost on their own, but CLI tools need system DNS.");
    console.log("  Enable systemd-resolved, or use dnsmasq:");
    console.log("    sudo dnf install dnsmasq");
    console.log(`    echo '${DNSMASQ_CONFIG}' | sudo tee /etc/dnsmasq.d/lazydev`);
    console.log("    sudo systemctl enable --now dnsmasq");
  }

  const portStatus = checkPort(port);
  if (portStatus === "ok") {
    console.log(`✓ Port ${port} is available`);
  } else if (portStatus === "in-use") {
    if (proxyIsRunning()) {
      console.log(`✓ Port ${port} is in use by LazyDev`);
    } else {
      console.log(`⚠ Port ${port} is in use by another process`);
      console.log(`  Find it with: ss -tlnp 'sport = :${port}'`);
      actionNeeded = true;
    }
  } else if (portStatus === "denied") {
    console.log(`⚠ Cannot bind port ${port} without extra permissions. Allow it with:`);
    console.log(`    echo 'net.ipv4.ip_unprivileged_port_start=${port}' | sudo tee /etc/sysctl.d/50-lazydev.conf && sudo sysctl --system`);
    console.log("  Or set settings.proxy_port to a port >= 1024.");
    actionNeeded = true;
  } else {
    console.log(`⚠ Could not check port ${port}: ${portStatus}`);
  }

  const capable = capableBunBinaries();
  if (capable.length === 0) {
    console.log("✓ bun has no file capabilities");
  } else {
    console.log("⚠ bun has file capabilities, so LazyDev can't see dev servers run with bun");
    for (const line of capabilityAdvice(capable, port)) console.log(`  ${line}`);
    actionNeeded = true;
  }

  return actionNeeded;
}
